<script lang="ts">
  // Settings > About > Open-source licenses. The list is generated by tools/licenses.py
  // (CI checks it is current): board firmware libraries, the UI's npm packages, Rust crates.
  import { FAST, scrim, sheet } from "./motion";
  import Icon from "./Icon.svelte";
  import licenses from "./licenses.json";

  let { onclose }: { onclose: () => void } = $props();
  type Item = { name: string; version: string; license: string };
  const groups: { title: string; items: Item[] }[] = [
    { title: "Board firmware", items: licenses.board },
    { title: "PC app interface", items: licenses.web },
    { title: "PC app (Rust crates)", items: licenses.rust },
  ];

  function key(e: KeyboardEvent) {
    if (e.key === "Escape") onclose();
  }
</script>

<svelte:window onkeydown={key} />

<div class="scrim" in:scrim out:scrim={{ duration: FAST }}>
  <div class="sheet" role="dialog" in:sheet out:sheet={{ duration: FAST }} aria-labelledby="lic-title" aria-modal="true">
    <div class="head">
      <h2 id="lic-title">Open-source licenses</h2>
      <button type="button" class="x" aria-label="Close" onclick={onclose}><Icon name="x" size={12} color="var(--label-2)" /></button>
    </div>
    <div class="list">
      <p class="intro">
        fenixOS is MIT licensed and built on these projects. Each keeps its own license; the full texts come with their
        source.
      </p>
      {#each groups as g (g.title)}
        <h3 class="section-title">{g.title}</h3>
        <div class="group">
          {#each g.items as it (it.name + it.version)}
            <div class="row">
              <p class="name">{it.name}{#if it.version}<span class="ver">{it.version}</span>{/if}</p>
              <p class="value">{it.license}</p>
            </div>
          {/each}
        </div>
      {/each}
    </div>
  </div>
</div>

